['Certainly! Below is a C program that implements the described functionality:

```c
#include <stdio.h>
#include <stdlib.h>

// Function to get the value at the given index in an array
int getValueFromArray(int arr[], int size, int index) {
    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1;
    }
}

int main() {
    // Read the size of the array from the standard input
    int size;
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    // Allocate memory for the array
    int* arr = (int*)malloc(size * sizeof(int));
    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return EXIT_FAILURE;
    }

    // Read the elements of the array from the standard input
    printf("Enter %d integers:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Read the index from the standard input
    int index;
    printf("Enter the index to retrieve: ");
    scanf("%d", &index);

    // Get the value at the given index
    int result = getValueFromArray(arr, size, index);

    // Free the allocated memory
    free(arr);

    // Return the result as the exit code
    return result;
}
```

### Explanation:
1. **getValueFromArray Function**:
   - This function takes an array `arr`, its `size`, and an `index` as parameters.
   - It checks if the `index` is within the bounds of the array (i.e., `index >= 0 && index < size`).
