int getValueAtIndex(int arr[], int size, int index) {
    if (index >= 0 && index < size) {
        return arr[index];
    } else {
        return -1; // Return -1 if index is out of bounds
    }
}

int main() {
    int size, index;

    // Prompt the user to enter the size of the array
    printf("Enter the size of the array: ");
    scanf("%d", &size);

    // Allocate memory for the array
    int *arr = (int *)malloc(size * sizeof(int));

    if (arr == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    // Prompt the user to enter the elements of the array
    printf("Enter %d elements for the array:\n", size);
    for (int i = 0; i < size; i++) {
        scanf("%d", &arr[i]);
    }

    // Prompt the user to enter the index they want to access
    printf("Enter the index you want to access: ");
    scanf("%d", &index);

    // Get the value at the given index
    int result = getValueAtIndex(arr, size, index);

    // Check if the result is -1 (out of bounds)
    if (result == -1) {
        printf("Index out of bounds. Returning -1\n");
    } else {
        printf("Value at index %d: %d\n", index, result);
    }

    // Free the allocated memory
    free(arr);

    return 0;
}
```

