    int b = rand() % 9001 + 1000;
    int c = rand() % 9001 + 1000;

    // Print the three integers
    printf("a : %d\n", a);
    printf("b : %d\n", b);
    printf("c : %d\n", c);

    // Calculate the sum of the three integers
    int sum = a + b + c;
    printf("sum: %d\n", sum);

    // Calculate the sum using long long to avoid overflow
    long long sum2 = (long long)a + (long long)b + (long long)c;
    printf("sum2: %lld\n", sum2);

    return 0;
}
```

### Explanation:
