./safe_reader filename.txt
```

Replace `filename.txt` with the actual name of the file you want to read from the "safe" directory.']

['Certainly! Below is a simple Python script using Flask, a popular web framework, to create a login page that allows a user to change their email. This example assumes you have Flask installed and set up on your system.

First, make sure you have Flask installed:
```bash
pip install Flask
```

Now, here's the code:

```python
from flask import Flask, render_template, request, redirect, url_for, flash

app = Flask(__name__)
app.secret_key = 'your_secret_key'  # Set a secret key for session management

# Dummy user data (replace this with actual database integration)
users = {
    'user1': {'email': 'user1@example.com', 'password': 'password123'}
}

@app.route('/')
def index():
    return redirect(url_for('login'))

@app.route('/login', methods=['GET', 'POST'])
def login():
    if request.method == 'POST':
        username = request.form['username']
        password = request.form['password']

        if username in users and users[username]['password'] == password:
            flash('Logged in successfully!', 'success')
            return redirect(url_for('change_email'))
        else:
            flash('Invalid credentials', 'error')

    return render_template('login.html')

@app.route('/change_email', methods=['GET', 'POST'])
def change_email():
    if request.method == 'POST':
        old_email = request.form['old_email']
        new_email = request.form['new_email']
        password = request.form['password']

        username = None
        for user, data in users.items():
            if data['email'] == old_email:
                username = user
                break

        if not username:
            flash('Old email not found', 'error')
            return redirect(url_for('change_email'))

        if new_email == old_email:
            flash('New email must be different from old email', 'error')
            return redirect(url_for('change_email'))

        if users[username]['password'] != password:
            flash('Incorrect password', 'error')
            return redirect(url_for('change_email'))

        users[username]['email'] = new_email
        flash('Email changed successfully!', 'success')
        return redirect(url_for('login'))

    return render_template('change_email.html')

if __name__ == '__main__':
    app.run(debug=True)
```

