#define MAX_FILE_SIZE 1024 * 1024 // 1MB buffer size

unsigned char calculateChecksum(const unsigned char *buffer, size_t length) {
    unsigned char checksum = 0;
    for (size_t i = 0; i < length; ++i) {
        checksum += buffer[i];
    }
    return checksum;
}

int main(int argc, char *argv[]) {
    if (argc != 4) {
        fprintf(stderr, "Usage: %s <input_file> <output_file> <buffer_size>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *inputFile = argv[1];
    const char *outputFile = argv[2];
    size_t bufferSize = atoi(argv[3]);

    if (bufferSize > MAX_FILE_SIZE) {
        fprintf(stderr, "Buffer size exceeds maximum allowed (%zu bytes)\n", MAX_FILE_SIZE);
        return EXIT_FAILURE;
    }

    unsigned char buffer[bufferSize];

    FILE *in = fopen(inputFile, "rb");
    if (!in) {
        perror("Failed to open input file");
        return EXIT_FAILURE;
    }

    size_t bytesRead = fread(buffer, 1, bufferSize, in);
    fclose(in);

    unsigned char checksum = calculateChecksum(buffer, bytesRead);

    FILE *out = fopen(outputFile, "wb");
    if (!out) {
        perror("Failed to open output file");
        return EXIT_FAILURE;
    }

    // Save the number of bytes read and the checksum
    fwrite(&bytesRead, sizeof(size_t), 1, out);
    fwrite(&checksum, sizeof(unsigned char), 1, out);

    fclose(out);

    printf("Bytes read: %zu\n", bytesRead);
    printf("Checksum: %02x\n", checksum);

    return EXIT_SUCCESS;
}
```

