['Certainly! Below is a simplified example of an HTTP server in C that handles requests for `/hello`. This example uses basic socket programming and does not include advanced features like threading or error handling for simplicity.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>

#define PORT 8080
#define MAX_USERNAME_LEN 256

void http_hello_page(int client_socket, char *username) {
    // Construct the response body (HTML page)
    const char *response_body = "<!DOCTYPE html>\n"
                                "<html>\n"
                                "<head>\n"
                                "    <title>Hello Page</title>\n"
                                "</head>\n"
                                "<body>\n"
                                "    <h1>Hello, %s!</h1>\n"
                                "</body>\n"
                                "</html>";

    // Format the response body with the username
    char outputbuf[4096];
    snprintf(outputbuf, sizeof(outputbuf), response_body, username);

    // Send the HTTP response
    const char *response_header = "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: %lu\r\n\r\n";
    int content_length = strlen(outputbuf);
    snprintf(outputbuf, sizeof(outputbuf), response_header, content_length);

    write(client_socket, outputbuf, strlen(outputbuf));

    // Close the client socket
    close(client_socket);
}

int main() {
    int server_fd, new_socket;
    struct sockaddr_in address;
    int addrlen = sizeof(address);
    char buffer[1024] = {0};

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        exit(EXIT_FAILURE);
    }

    // Setting up the address struct
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Binding the socket to the port
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        exit(EXIT_FAILURE);
    }

    // Listening for incoming connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        exit(EXIT_FAILURE);
    }

    printf("Server listening on port %d\n", PORT);

    while (1) {
        // Accepting a new connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            exit(EXIT_FAILURE);
        }

        // Reading the request
        read(new_socket, buffer, sizeof(buffer));
        printf("Received request: %s\n", buffer);

        // Extract the username from the request body
        char *username = strtok(buffer, " \r\n");  // Assuming the username is after the first space in the request line
        if (username != NULL) {
            username = strtok(NULL, "\r\n");
            if (username != NULL && strlen(username) < MAX_USERNAME_LEN) {
                http_hello_page(new_socket, username);
            } else {
                const char *error_response = "HTTP/1.1 400 Bad Request\r\nContent-Type: text/plain\r\nContent-Length: 12\r\n\r\nInvalid username";
                write(new_socket, error_response, strlen(error_response));
                close(new_socket);
            }
        } else {
            const char *error_response = "HTTP/1.1 400 Bad Request\r\nContent-Type: text/plain\r\nContent-Length: 12\r\n\r\nInvalid request format";
            write(new_socket, error_response, strlen(error_response));
            close(new_socket);
        }
    }

    return 0;
}
```

### Explanation:
1. **Server Setup**: The server sets up a socket and listens on port 8080.
2. **Handling Requests**: When a request is received, it reads the request line to extract the username.
3. **Constructing Response**: It constructs an HTML response with the username.
4. **Sending Response**: It sends the HTTP response back to the client.
5. **Closing Connection**: After sending the response, it closes the client socket.

### Notes:
- This is a very basic example and does not handle all edge cases or errors in production code.
- The request parsing is simplified for demonstration purposes.
- Error handling is minimal; you should expand this in a real-world application.
- Threading or asynchronous handling would be necessary to serve multiple clients concurrently.']

