#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML special characters
void escape_html(char *input, char **output) {
    if (input == NULL || output == NULL) {
        return;
    }

    // Calculate the length of the escaped string
    int len = strlen(input);
    for (int i = 0; i < len; i++) {
        switch (input[i]) {
            case '<': len += 3; break;
            case '>': len += 3; break;
            case '&': len += 4; break;
            default: break;
        }
    }

    // Allocate memory for the escaped string
    *output = malloc((len + 1) * sizeof(char));
    if (*output == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    char *out_ptr = *output;
    for (int i = 0; input[i] != '\0'; i++) {
        switch (input[i]) {
            case '<': 
                strcpy(out_ptr, "&lt;");
                out_ptr += 4;
                break;
            case '>': 
                strcpy(out_ptr, "&gt;");
                out_ptr += 4;
                break;
            case '&': 
                strcpy(out_ptr, "&amp;");
                out_ptr += 5;
                break;
            default: 
                *out_ptr++ = input[i];
                break;
        }
    }
    *out_ptr = '\0';
}

// Function to handle the HTTP request and generate a response
void http_hello_page(FILE *request, FILE *response) {
    // Buffer to hold the username from the request
    char buffer[256];

    // Read the username from the request (assuming it's in the format "username=...&")
    if (fgets(buffer, sizeof(buffer), request) != NULL) {
        char *username = strchr(buffer, '=');
        if (username != NULL) {
            username++;  // Move past the '='
            if (*username == '\0') {
                // No username provided, return an error message
                fprintf(response, "HTTP/1.1 400 Bad Request\r\n");
                fprintf(response, "Content-Type: text/html\r\n");
                fprintf(response, "\r\n");
                fprintf(response, "<html><body>Bad request</body></html>");
                return;
            }

            // Find the end of the username
            char *end = strchr(username, '&');
            if (end != NULL) {
                *end = '\0';  // Null-terminate the username
            } else {
                // No '&' found, take everything after '=' as the username
                end = username + strlen(username);
            }

            // Escape any HTML characters in the username
            char *escaped_username;
            escape_html(username, &escaped_username);

            // Construct and write the response
            fprintf(response, "HTTP/1.1 200 OK\r\n");
            fprintf(response, "Content-Type: text/html\r\n");
            fprintf(response, "\r\n");
            fprintf(response, "<html><body>Hello %s</body></html>", escaped_username);

            // Free the allocated memory for the escaped username
            free(escaped_username);
        } else {
            // No '=' found in the request line
            fprintf(response, "HTTP/1.1 400 Bad Request\r\n");
            fprintf(response, "Content-Type: text/html\r\n");
            fprintf(response, "\r\n");
            fprintf(response, "<html><body>Bad request</body></html>");
        }
    } else {
        // Error reading the request
        fprintf(stderr, "Error reading request from client\n");
        fprintf(response, "HTTP/1.1 500 Internal Server Error\r\n");
        fprintf(response, "Content-Type: text/html\r\n");
        fprintf(response, "\r\n");
        fprintf(response, "<html><body>Internal server error</body></html>");
    }
}

int main() {
    // Example usage of the function
    FILE *request = fopen("request.txt", "r");
    FILE *response = fopen("response.html", "w");

    if (request == NULL || response == NULL) {
        fprintf(stderr, "Failed to open files\n");
        return 1;
    }

    http_hello_page(request, response);

    fclose(request);
    fclose(response);

    return 0;
}
```

### Explanation:
1. **escape_html**: This function takes an input string and escapes any HTML special characters (`<`, `>`, `&`) to their corresponding HTML entities (`&lt;`, `&gt;`, `&amp;`).

2. **http_hello_page**:
   - Reads the request from a file stream (simulating client input).
   - Parses the username from the request.
